function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  let centerX = W / 2;
  let centerY = H / 2;
  let radius = 50 + 20 * Math.sin(t);
  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, 2 * Math.PI);
  ctx.stroke();
  let memoX = centerX + 30 * Math.cos(3 * t);
  let memoY = centerY + 30 * Math.sin(3 * t);
  ctx.beginPath();
  ctx.arc(memoX, memoY, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(memoX, memoY);
  ctx.lineTo(centerX, centerY);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(centerX, centerY, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.globalAlpha = 0.5 + 0.5 * Math.sin(2 * t);
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Memory', centerX, centerY - radius - 20);
  ctx.globalAlpha = 1;
  ctx.beginPath();
  ctx.moveTo(centerX, centerY);
  ctx.lineTo(centerX, H);
  ctx.setLineDash([10, 10]);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.restore();
}
